contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function transferFrom(address _from, address _to, uint256 _value) external returns (bool) {
        return false;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool allSucceeded = true;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok,) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            if (!ok) {
                allSucceeded = false;
            }
        }

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted == allSucceeded);
    }

    receive() external payable {}
}

